-- All fixtures, auth records and storage metadata roll back. No real business records changed.
BEGIN;
DO $$
DECLARE driver_user uuid:=gen_random_uuid(); other_user uuid:=gen_random_uuid(); customer_user uuid:=gen_random_uuid(); office uuid:=gen_random_uuid();
 driver uuid; other_driver uuid; customer uuid; vehicle uuid; truck uuid; shipment uuid; delivery uuid;
 incident uuid:=gen_random_uuid(); text_incident uuid:=gen_random_uuid(); expense uuid:=gen_random_uuid(); expense2 uuid:=gen_random_uuid();
 attachment uuid; path text; receipt text; version timestamptz; records jsonb; marker text:='evidence-test-'||gen_random_uuid(); n integer;
BEGIN
 INSERT INTO auth.users(id,email,raw_app_meta_data,raw_user_meta_data) VALUES
 (driver_user,marker||'-driver@example.invalid','{}','{}'),(other_user,marker||'-other@example.invalid','{}','{}'),
 (customer_user,marker||'-customer@example.invalid','{}','{}'),(office,marker||'-office@example.invalid','{}','{}');
 UPDATE public.users SET role='driver' WHERE id IN (driver_user,other_user);
 UPDATE public.users SET role='staff' WHERE id=office;
 SELECT id INTO customer FROM public.customers WHERE user_id=customer_user;
 INSERT INTO public.drivers(user_id,full_name,license_number) VALUES(driver_user,marker,marker) RETURNING id INTO driver;
 INSERT INTO public.drivers(user_id,full_name,license_number) VALUES(other_user,marker||'-other',marker||'-other') RETURNING id INTO other_driver;
 INSERT INTO public.vehicle_types(name,default_capacity_kg) VALUES(marker,1000) RETURNING id INTO vehicle;
 INSERT INTO public.trucks(plate_number,vehicle_type_id,capacity_kg) VALUES(marker,vehicle,1000) RETURNING id INTO truck;
 INSERT INTO public.shipments(customer_id,status,pickup_address,dropoff_address) VALUES(customer,'in_transit',marker,marker) RETURNING id INTO shipment;
 INSERT INTO public.deliveries(shipment_id,driver_id,truck_id,status) VALUES(shipment,driver,truck,'in_transit') RETURNING id INTO delivery;
 path:=delivery||'/incident-'||incident||'-1.jpg'; receipt:=delivery||'/receipt-'||expense||'.jpg';
 PERFORM set_config('request.jwt.claim.sub',driver_user::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',driver_user,'role','authenticated')::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 INSERT INTO storage.objects(bucket_id,name,owner,metadata) VALUES('delivery-documents',path,driver_user,'{"mimetype":"image/jpeg","size":100}'),('delivery-documents',receipt,driver_user,'{"mimetype":"image/jpeg","size":100}');
 PERFORM public.driver_report_incident_evidence(delivery,incident,'traffic','Fictional traffic evidence',5,ARRAY[path]);
 PERFORM public.driver_report_incident_evidence(delivery,incident,'traffic','Fictional traffic evidence',5,ARRAY[path]);
 IF (SELECT count(*) FROM public.incident_attachments WHERE incident_id=incident)<>1 THEN RAISE EXCEPTION 'Photo replay duplicated';END IF;
 BEGIN PERFORM public.driver_report_incident_evidence(delivery,incident,'traffic','Changed fictional evidence',5,ARRAY[path]);RAISE EXCEPTION 'Changed incident replay accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INCIDENT_REQUEST_CONFLICT' THEN RAISE;END IF;END;
 PERFORM public.driver_report_incident_evidence(delivery,text_incident,'other','Text incident retained',0,'{}');
 IF NOT EXISTS(SELECT 1 FROM public.delivery_incidents WHERE id=text_incident) THEN RAISE EXCEPTION 'Text incident lost';END IF;
 BEGIN PERFORM public.driver_report_incident_evidence(delivery,gen_random_uuid(),'other','Missing upload',0,ARRAY[delivery||'/incident-'||gen_random_uuid()||'-1.jpg']);RAISE EXCEPTION 'Missing upload accepted';EXCEPTION WHEN insufficient_privilege OR check_violation THEN NULL;END;
 BEGIN PERFORM public.driver_report_incident_evidence(delivery,gen_random_uuid(),'other','Too many photos',0,ARRAY[path,path,path,path]);RAISE EXCEPTION 'Excess photos accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_INCIDENT_PHOTOS' THEN RAISE;END IF;END;
 INSERT INTO public.delivery_expenses(id,delivery_id,driver_id,category,amount,receipt_path,status) VALUES(expense,delivery,driver,'parking',50,receipt,'pending'),(expense2,delivery,driver,'toll',75,NULL,'pending');
 BEGIN INSERT INTO public.delivery_expenses(delivery_id,driver_id,category,amount,status) VALUES(delivery,driver,'parking',10,'approved');RAISE EXCEPTION 'Driver self-approved';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN INSERT INTO public.delivery_expenses(delivery_id,driver_id,category,amount,receipt_path,status) VALUES(delivery,driver,'parking',10,delivery||'/receipt-missing.jpg','pending');RAISE EXCEPTION 'Missing receipt accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 records:=public.mobile_driver_evidence(shipment);
 IF jsonb_array_length(records->'expenses')<>2 OR jsonb_array_length(records->'incident_evidence')<>1 THEN RAISE EXCEPTION 'Evidence records incomplete';END IF;
 attachment:=(records->'incident_evidence'->0->>'id')::uuid;
 IF public.mobile_delivery_evidence_file(shipment,'incident',attachment)<>path OR public.mobile_delivery_evidence_file(shipment,'expense',expense)<>receipt THEN RAISE EXCEPTION 'Wrong authorized path';END IF;
 -- Emulate the Storage API's transaction-local deletion flag for synthetic metadata only.
 PERFORM set_config('storage.allow_delete_query','true',true);
 DELETE FROM storage.objects WHERE bucket_id='delivery-documents' AND name IN(path,receipt);
 IF (SELECT count(*) FROM storage.objects WHERE bucket_id='delivery-documents' AND name IN(path,receipt))<>2 THEN RAISE EXCEPTION 'Committed files deletable';END IF;
 SELECT updated_at INTO version FROM public.delivery_expenses WHERE id=expense;
 BEGIN PERFORM public.office_review_expense(expense,version,'approved','Driver tries approval');RAISE EXCEPTION 'Driver review allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub',other_user::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',other_user,'role','authenticated')::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='delivery-documents' AND name IN(path,receipt)) OR EXISTS(SELECT 1 FROM public.incident_attachments WHERE incident_id=incident) THEN RAISE EXCEPTION 'Other driver file leak';END IF;
 BEGIN PERFORM public.mobile_delivery_evidence_file(shipment,'expense',expense);RAISE EXCEPTION 'Other driver RPC leak';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN INSERT INTO storage.objects(bucket_id,name,owner,metadata) VALUES('delivery-documents',delivery||'/incident-'||gen_random_uuid()||'-1.jpg',other_user,'{"mimetype":"image/jpeg","size":100}');RAISE EXCEPTION 'Other driver upload';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub',customer_user::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',customer_user,'role','authenticated')::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='delivery-documents' AND name IN(path,receipt)) THEN RAISE EXCEPTION 'Customer file leak';END IF;
 BEGIN PERFORM public.mobile_driver_evidence(shipment);RAISE EXCEPTION 'Customer expense leak';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub',office::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',office,'role','authenticated')::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 IF (SELECT count(*) FROM storage.objects WHERE bucket_id='delivery-documents' AND name IN(path,receipt))<>2 THEN RAISE EXCEPTION 'Office file access denied';END IF;
 PERFORM public.office_review_expense(expense,version,'approved','Receipt matches parking amount');
 BEGIN PERFORM public.office_review_expense(expense,version,'rejected','Stale second review');RAISE EXCEPTION 'Stale review accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'STALE_EXPENSE_REVIEW' THEN RAISE;END IF;END;
 SELECT updated_at INTO version FROM public.delivery_expenses WHERE id=expense2;
 PERFORM public.office_review_expense(expense2,version,'rejected','Missing supporting receipt');
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub',driver_user::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',driver_user,'role','authenticated')::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 records:=public.mobile_driver_evidence(shipment);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(records->'expenses') e WHERE e->>'status'='approved' AND e->>'review_reason'='Receipt matches parking amount')
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(records->'expenses') e WHERE e->>'status'='rejected' AND e->>'review_reason'='Missing supporting receipt') THEN RAISE EXCEPTION 'Review feedback missing';END IF;
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claims','{}',true);
 UPDATE public.users SET is_active=false WHERE id=driver_user;
 PERFORM set_config('request.jwt.claim.sub',driver_user::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',driver_user,'role','authenticated')::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='delivery-documents' AND name IN(path,receipt)) THEN RAISE EXCEPTION 'Inactive account file leak';END IF;
 BEGIN PERFORM public.mobile_driver_evidence(shipment);RAISE EXCEPTION 'Inactive RPC accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claims','{"role":"anon"}',true);
 EXECUTE 'SET LOCAL ROLE anon';
 BEGIN PERFORM public.mobile_driver_evidence(shipment);RAISE EXCEPTION 'Anon RPC accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
END $$;
ROLLBACK;
SELECT 'PASS: incident text/photos/replay, expense persistence/review, private file ownership, customer/other-driver/inactive/anon isolation, stale decisions and committed-file protection; fixtures rolled back' result;
